$conn = New-Object System.Data.SqlClient.SqlConnection("Server=.\sql2022;Database=GR_EMA_DISTRIBUTION;User Id=sa;Password=1234;TrustServerCertificate=True;"); $conn.Open(); $cmd = $conn.CreateCommand(); $cmd.CommandText = "SELECT TOP 1 YEAR(MV_PointDate), MONTH(MV_PointDate) FROM RT_MOUVEMENT WHERE MV_Point = 1 AND MV_PointDate IS NOT NULL AND MV_Domaine IN (1,3) AND MV_DECAISSE = 1"; $reader = $cmd.ExecuteReader(); while ($reader.Read()) { Write-Host "$($reader.GetValue(0))-$($reader.GetValue(1))" } $conn.Close()
